pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzValue) public {
        fuzzValue = bound(fuzzValue, 0, 100 ether);
        address actor = address(0x1234);
        vm.deal(actor, fuzzValue);
        vm.warp(block.timestamp + 1000);
        vm.prank(actor);
        (bool success,) = address(c).call{value: fuzzValue}("");
        assertTrue(!success || fuzzValue == 10 ether);
    }
}
